from topics_a import t, T
M='mortgage'
t('mortgage-broker',M,'a mortgage broker',"Mortgage brokers compare mortgages from different lenders, check affordability and manage your application through to offer.",["Ask whether they search the whole market.","Understand fees before you start.","Get a decision in principle early."])
t('mortgage-advisor',M,'a mortgage adviser',"Mortgage advisers recommend suitable mortgages based on your circumstances, and are regulated by the FCA.",["Advisers may work for a broker or a lender.","Advice must be suitable for you.","Ask about protection too."])
t('independent-mortgage-advisor',M,'an independent mortgage adviser',"Independent mortgage advisers search across the market rather than a single lender, and explain how they are paid.",["\"Whole of market\" is the term to ask about.","Some deals are direct-only.","Fees vary by firm."])
t('remortgage-advisor',M,'a remortgage adviser',"Remortgage advisers compare your current lender's product transfer with deals elsewhere when your fixed rate ends.",["Start a few months before your deal ends.","Product transfers can be simpler.","Early repayment charges may apply."])
t('remortgage-mortgage',M,'a remortgage',"A remortgage replaces your current mortgage with a new deal, either with your lender or a new one, to change rate, term or borrowing.",["Compare total costs, not just rates.","Legal work may be free with some lenders.","Check early repayment charges."])
t('bridging-mortgage',M,'a bridging loan',"Bridging loans are short-term secured finance, used for chain breaks, auctions, refurbishment or quick purchases.",["Exit strategy is essential.","Rates are higher than mortgages.","Regulated bridging covers your own home."])
t('bridging-finance-broker',M,'a bridging finance broker',"Bridging finance brokers find short-term lending for property purchases and projects, comparing rates, fees and terms.",["Speed and certainty matter.","Check all fees.","Plan the exit before borrowing."])
t('commercial-mortgage',M,'a commercial mortgage',"Commercial mortgages fund the purchase or refinance of business premises or investment property.",["Lenders assess the business and property.","Deposits are usually larger.","Most commercial lending is unregulated."])
t('commercial-mortgage-broker',M,'a commercial mortgage broker',"Commercial mortgage brokers arrange finance for offices, shops, industrial units, semi-commercial and investment property.",["Business accounts are needed.","Valuations take longer.","Ask about lender relationships."])
t('contractor-mortgage',M,'a contractor mortgage',"Contractor mortgages let lenders assess day-rate contractors on contract income rather than limited company accounts.",["Contract history matters.","Specialist lenders may help.","IR35 status can affect assessment."])
t('contractor-mortgage-broker',M,'a contractor mortgage broker',"Contractor mortgage brokers know which lenders accept day-rate income and how to present contracts.",["Bring current contracts.","Gaps between contracts are considered.","Specialist knowledge helps."])
t('expat-mortgage',M,'an expat mortgage',"Expat mortgages let UK nationals living abroad buy or remortgage UK property, often buy-to-let.",["Fewer lenders offer expat deals.","Foreign currency income affects borrowing.","Larger deposits are common."])
t('expat-mortgage-broker',M,'an expat mortgage broker',"Expat mortgage brokers find lenders for applicants living overseas and handle remote applications.",["Remote ID checks are needed.","Currency matters.","Allow longer timescales."])
t('guarantor-mortgage',M,'a guarantor mortgage',"Guarantor and family-assisted mortgages let a family member support a borrower with their savings or property.",["Guarantors take on risk.","Guarantors should get independent advice.","Joint borrower, sole proprietor options exist."])
t('offset-mortgage',M,'an offset mortgage',"Offset mortgages link savings to your mortgage, so you pay interest only on the difference.",["Suits people with substantial savings.","Rates can be slightly higher.","Flexibility is the benefit."])
FA='fa'
t('financial-advisor',FA,'a financial adviser',"Financial advisers recommend how to save, invest, protect and plan for retirement based on your goals and circumstances.",["Check FCA authorisation.","Know whether advice is independent or restricted.","Agree ongoing service in writing."])
t('ifa',FA,'an IFA',"An IFA (independent financial adviser) considers products from across the market when recommending pensions, investments and protection.",["Independent status must be justified.","Check charges in pounds.","Ask about qualifications."])
t('independent-financial-advisor',FA,'an independent financial adviser',"Independent financial advisers give unbiased advice across the market and must not be tied to particular providers.",["Restricted advice is not necessarily worse.","Check the FCA register.","Get recommendations in writing."])
t('personal-financial-advisor',FA,'a personal financial adviser',"Personal financial advisers help individuals and families with savings, investments, pensions and protection.",["Start with goals.","Review regularly.","Understand risk."])
t('investment-financial-advisor',FA,'an investment adviser',"Investment advisers recommend portfolios and wrappers such as ISAs and pensions to suit your goals and risk.",["Diversification matters.","Costs affect returns.","Past performance is not a guide."])
t('ethical-financial-advisor',FA,'an ethical financial adviser',"Ethical financial advisers build investment plans that reflect your values, using ESG and sustainable funds.",["Labels vary; ask about screening.","The FCA has sustainability disclosure rules.","Balance values and risk."])
t('expat-financial-advisor',FA,'an expat financial adviser',"Expat financial advisers help people living abroad or moving to or from the UK with pensions, investments and tax.",["Overseas pension transfers carry risk.","Check regulation in both countries.","Currency risk matters."])
t('divorce-financial-advisor',FA,'a divorce financial adviser',"Divorce financial advisers help separating couples understand assets, pensions and future income, often alongside solicitors.",["Pensions are often the largest asset.","Pension sharing orders need expert input.","Budget for the future."])
t('business-financial-advisor',FA,'a business financial adviser',"Business financial advisers help owners with profit extraction, pensions, protection, succession and exit planning.",["Company pension contributions can be efficient.","Shareholder protection helps.","Plan exits early."])
t('cashflow-planning-advisor',FA,'a cash-flow planning adviser',"Cash-flow planning advisers model your income, spending and assets over time to show whether goals are achievable.",["Models depend on assumptions.","Review plans annually.","Stress tests show risks."])
t('protection-financial-advisor',FA,'a protection adviser',"Protection advisers recommend life insurance, income protection and critical illness cover to protect your family.",["Underwriting depends on health.","Trusts can speed payouts.","Review after life changes."])
t('financial-planner',FA,'a financial planner',"Financial planners take a whole-life view of your finances, linking goals with investments, pensions, tax and protection.",["Planning is broader than product advice.","Cash-flow models support decisions.","Ongoing reviews keep plans on track."])
t('chartered-financial-planner',FA,'a chartered financial planner',"Chartered financial planners hold advanced CII qualifications, and chartered firms meet further standards.",["Check the CII or PFS directory.","Chartered firms commit to professionalism.","Ask about planning process."])
t('certified-financial-planner',FA,'a certified financial planner',"CFP professionals hold the CFP certification, awarded in the UK by the CISI, covering financial planning practice and ethics.",["Check CISI records.","CFP focuses on planning.","Ask about ongoing service."])
t('wealth-planner',FA,'a wealth planner',"Wealth planners help people with significant assets plan investments, tax, estate and family wealth.",["Coordinate with solicitors and accountants.","Family governance can help.","Fees should be transparent."],hub='wealth-management')
PE='pension'
t('pension-advisor',PE,'a pension adviser',"Pension advisers help you build, review and take your pensions, from workplace schemes to SIPPs and annuities.",["Check charges and guarantees.","Use your state pension forecast.","Plan tax-efficient withdrawals."])
t('pension-consultant',PE,'a pension consultant',"Pension consultants advise individuals or employers on scheme choice, reviews and benefits strategy.",["Employer schemes have governance duties.","Charges affect outcomes.","Communication helps staff engage."])
t('pension-financial-advisor',PE,'a pension financial adviser',"Pension financial advisers combine pension advice with wider planning on investments, tax and retirement income.",["Holistic advice spots trade-offs.","Death benefits matter.","Review regularly."])
t('pension-transfer-advisor',PE,'a pension transfer adviser',"Pension transfer advisers assess whether moving a pension makes sense, including specialist advice on defined benefit transfers.",["Guaranteed benefits are valuable.","Specialist permissions are needed for DB transfers.","Scams target transfers."])
t('pension-consolidation-advisor',PE,'a pension consolidation adviser',"Pension consolidation advisers check old pensions for charges, guarantees and exit fees before recommending whether to combine them.",["Find lost pensions with the Pension Tracing Service.","Some guarantees are lost on transfer.","Lower charges help growth."])
t('drawdown-pension-advisor',PE,'a pension drawdown adviser',"Drawdown advisers help you take a flexible income from your pension while keeping it invested.",["Withdrawal rates affect sustainability.","Investment risk remains.","Tax applies to withdrawals beyond tax-free cash."])
t('annuity-advisor',PE,'an annuity adviser',"Annuity advisers compare guaranteed incomes across providers, including enhanced annuities for health conditions.",["Shopping around can increase income.","Health can improve rates.","Options include inflation protection."])
t('auto-enrolment-advisor',PE,'an auto-enrolment adviser',"Auto-enrolment advisers help employers set up compliant workplace pensions, assess staff and meet Pensions Regulator duties.",["Employers must enrol eligible staff.","Declarations of compliance are required.","Payroll integration matters."])
t('retirement-advisor',PE,'a retirement adviser',"Retirement advisers help you decide when you can retire and how to turn savings into income.",["Plan for a long retirement.","Consider care costs.","Use cash-flow modelling."])
t('retirement-financial-advisor',PE,'a retirement financial adviser',"Retirement financial advisers coordinate pensions, savings, property and tax to support a sustainable retirement income.",["Sequence of withdrawals matters.","State pension timing helps.","Review annually."])
t('retirement-planner',PE,'a retirement planner',"Retirement planners map your goals, model income and recommend steps to retire on your terms.",["Start early.","Know your target income.","Plan for inflation."])
t('equity-release-advisor','equity','an equity release adviser',"Equity release advisers explain lifetime mortgages and home reversion plans, and whether they suit your later-life needs.",["Involve family where possible.","Compare alternatives.","Check Equity Release Council membership."])
t('equity-release-broker','equity','an equity release broker',"Equity release brokers compare plans across lenders and features such as drawdown and voluntary repayments.",["Whole-of-market access matters.","Features vary between plans.","Fees must be explained."])
